from abc import ABC, abstractmethodfrom typing import Optional, Listimport jax.numpy as npclass Transform(ABC):    """Base class for transformations with chain support"""        def __init__(self, name: Optional[str] = None):        self.name = name or self.__class__.__name__        @abstractmethod    def __call__(self, x: np.ndarray):        """Apply transformation to input design variables"""        pass        def __add__(self, other: 'Transform'):        """Support chain operations with + operator"""        if isinstance(other, TransformChain):            return TransformChain([self] + other.transforms)        return TransformChain([self, other])        def __repr__(self):        return f"{self.__class__.__name__}()"class TransformChain(Transform):    """Chain multiple transformations together"""        def __init__(self, transforms: List[Transform]):        super().__init__()        self.transforms = transforms        def __call__(self, x: np.ndarray):        current = x        for transform in self.transforms:            current = transform(current)        return current        def __add__(self, other: Transform):        if isinstance(other, TransformChain):            return TransformChain(self.transforms + other.transforms)        return TransformChain(self.transforms + [other])        def __repr__(self):        names = [t.__class__.__name__ for t in self.transforms]        return f"TransformChain({names})"    